import java.util.*; import java.io.*; public class Main { static class FastScanner { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st; String next() { while (st == null || !st.hasMoreTokens()) { try { String l = br.readLine(); if (l == null) return null; st = new StringTokenizer(l); } catch (IOException e) { return null; } } return st.nextToken(); } int nextInt() { return Integer.parseInt(next()); } } public static void main(String[] args) { FastScanner sc = new FastScanner(); PrintWriter out = new PrintWriter(System.out); int t = sc.nextInt(); while (t-- > 0) { int a = sc.nextInt(); int b = sc.nextInt(); int s = a + b; int minMoves = Integer.MAX_VALUE; for (int bNew = 1; bNew < s; bNew++) { int aNew = s - bNew; if (aNew % bNew == 0) { int moves = Math.abs(a - aNew); if (moves < minMoves) { minMoves = moves; } } } out.println(minMoves); } out.flush(); out.close(); } }